INSERT INTO `consoles` VALUES (1,549.99,'Sony home console featuring high performance, fast loading times and support for modern games with advanced graphics.','PlayStation 5'),(2,549.99,'Microsoft high-end console designed for powerful gaming, fast loading and high-resolution graphics.','Xbox Series X'),(3,299.99,'Compact Microsoft console offering digital gaming, fast loading times and access to a large library of Xbox games.','Xbox Series S'),(4,299.99,'Hybrid Nintendo console that can be used as both a home console and a portable gaming device.','Nintendo Switch'),(5,349.99,'Enhanced Nintendo Switch model featuring a larger OLED screen, improved audio and increased internal storage.','Nintendo Switch OLED'),(6,399.99,'Portable gaming device by Valve that allows users to play a large selection of PC games on the go.','Steam Deck'),(7,299.99,'Sony home console with an extensive library of games, multimedia features and support for online gaming.','PlayStation 4'),(8,249.99,'Microsoft home console offering access to a wide selection of games, multimedia applications and online services.','Xbox One'),(9,199.99,'Nintendo home console featuring a unique GamePad controller with an integrated touchscreen.','Nintendo Wii U'),(10,199.99,'Portable Nintendo console featuring stereoscopic 3D gaming, dual screens and a large library of exclusive titles.','Nintendo 3DS'),(11,199.99,'Sony home console known for its extensive game library, Blu-ray support and online gaming capabilities.','PlayStation 3'),(12,179.99,'Microsoft home console with a large game library, online multiplayer capabilities and digital entertainment services.','Xbox 360');
